"""Regenerate profiles/samsung-audio-group-1..16.yml and src/custom_caps.lua.

Usage:
  python make_profiles.py                 # standard capabilities only
  python make_profiles.py <namespace>     # also adds the custom EQ preset capability
                                          # (<namespace>.eqPreset)
  python make_profiles.py --no-eq         # no custom capabilities at all
The namespace is remembered in capabilities/namespace.txt, so later runs can omit it.
"""
import os, sys

HERE = os.path.dirname(os.path.abspath(__file__))
NS_FILE = os.path.join(HERE, "capabilities", "namespace.txt")
MAX = 16

args = [a for a in sys.argv[1:] if not a.startswith("--")]
flags = {a for a in sys.argv[1:] if a.startswith("--")}
NO_EQ = "--no-eq" in flags
ns = args[0].strip() if args else ""
if not ns and os.path.exists(NS_FILE):
    ns = open(NS_FILE, encoding="utf-8").read().strip()
if ns:
    os.makedirs(os.path.dirname(NS_FILE), exist_ok=True)
    with open(NS_FILE, "w", encoding="utf-8", newline="\n") as f:
        f.write(ns + "\n")

MAIN = 'name: {name}\ncomponents:\n  - id: main\n    label: All Speakers\n    capabilities:\n      - id: switch\n        version: 1\n      - id: mediaPlayback\n        version: 1\n        config:\n          values:\n            - key: "{{enumCommands}}"\n              enabledValues:\n                - \'play\'\n                - \'pause\'\n                - \'stop\'\n            - key: "playbackStatus.value"\n              enabledValues:\n                - \'playing\'\n                - \'paused\'\n                - \'stopped\'\n      - id: mediaTrackControl\n        version: 1\n      - id: audioVolume\n        version: 1\n      - id: audioMute\n        version: 1\n      - id: audioTrackData\n        version: 1\n      - id: audioNotification\n        version: 1\n      - id: refresh\n        version: 1\n    categories:\n      - name: Speaker\n'
SPEAKER = '  - id: {cid}\n    label: {label}\n    capabilities:\n      - id: switch\n        version: 1\n      - id: mediaPlayback\n        version: 1\n        config:\n          values:\n            - key: "{{enumCommands}}"\n              enabledValues:\n                - \'play\'\n                - \'pause\'\n                - \'stop\'\n            - key: "playbackStatus.value"\n              enabledValues:\n                - \'playing\'\n                - \'paused\'\n                - \'stopped\'\n      - id: mediaTrackControl\n        version: 1\n      - id: audioVolume\n        version: 1\n      - id: audioMute\n        version: 1\n      - id: audioTrackData\n        version: 1\n      - id: audioNotification\n        version: 1\n      - id: mediaInputSource\n        version: 1\n      - id: mediaPlaybackShuffle\n        version: 1\n      - id: mediaPlaybackRepeat\n        version: 1\n{custom}    categories:\n      - name: Speaker\n'
PREFS = "preferences:" + '\n  - name: "pollInterval"\n    title: "Status refresh interval (seconds)"\n    description: "How often each speaker is checked"\n    required: false\n    preferenceType: integer\n    definition:\n      minimum: 15\n      maximum: 600\n      default: 60\n  - name: "speakerIps"\n    title: "Speaker IPs (always included)"\n    description: "Comma-separated. These are always checked even if network discovery misses them. Newly discovered speakers are still added automatically."\n    required: false\n    preferenceType: string\n    definition:\n      stringType: text\n      default: "none"\n  - name: "excludedIps"\n    title: "Excluded IPs"\n    description: "Comma-separated. Speakers at these IPs are removed and never added, even if discovered or listed above."\n    required: false\n    preferenceType: string\n    definition:\n      stringType: text\n      default: "none"\n  - name: "resetSpeakers"\n    title: "Rebuild speaker list"\n    description: "Flip this switch to forget all speakers and search again"\n    required: false\n    preferenceType: boolean\n    definition:\n      default: false\n'
CUSTOM = "      - id: {ns}.eqPreset\n        version: 1\n"
ns_used = "" if NO_EQ else ns

for n in range(1, MAX + 1):
    out = MAIN.replace("{name}", f"samsung-audio-group-{n}")
    for i in range(1, n + 1):
        out += (SPEAKER.replace("{cid}", f"speaker{i}")
                       .replace("{label}", f"Speaker {i}")
                       .replace("{custom}", CUSTOM.replace("{ns}", ns_used) if ns_used else ""))
    out += PREFS
    with open(os.path.join(HERE, "profiles", f"samsung-audio-group-{n}.yml"), "w", encoding="utf-8", newline="\n") as f:
        f.write(out)

with open(os.path.join(HERE, "src", "custom_caps.lua"), "w", encoding="utf-8", newline="\n") as f:
    f.write("-- generated by make_profiles.py\n")
    f.write("return { namespace = %s }\n" % (f'"{ns_used}"' if ns_used else "nil"))

what = f"EQ preset from namespace '{ns_used}'" if ns_used else "no EQ capabilities"
print(f"wrote {MAX} profiles ({what})")
